{
  "definition_simple": "在竞争或比赛中取得胜利。",
  "definition_standard": "在竞赛、比赛或对抗中取得胜利，成为赢家。",
  "pos": "动词",
  "semantic_class": "action",
  "sentences": [
    {"sentence": "我们队获胜了。", "difficulty": "T1"},
    {"sentence": "他获胜了。", "difficulty": "T1"},
    {"sentence": "在昨天的比赛中，他获胜了。", "difficulty": "T2"},
    {"sentence": "经过激烈的竞争，他们最终获胜。", "difficulty": "T2"},
    {"sentence": "这支球队在决赛中以3:1获胜。", "difficulty": "T3"},
    {"sentence": "他在选举中获胜，成为新一任主席。", "difficulty": "T3"},
    {"sentence": "尽管面临诸多挑战，她依然凭借实力获胜。", "difficulty": "T4"},
    {"sentence": "该方案在投票中获胜，获得了多数支持。", "difficulty": "T4"},
    {"sentence": "在商战中，只有不断创新才能最终获胜。", "difficulty": "T5"},
    {"sentence": "在哲学辩论中，他凭借严密的逻辑推理获胜，令对手折服。", "difficulty": "T6"}
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "获释",
      "explanation": "“获释”与“获胜”读音相近（获同音，释与胜韵母i和eng在某些口音中不易区分），容易造成听觉混淆。"
    },
    {
      "word": "获准",
      "explanation": "“获准”的韵母un与“获胜”的eng发音接近，且声母zh和sh都是舌尖后音，容易听错。"
    },
    {
      "word": "火盛",
      "explanation": "“火盛”与“获胜”声母相同，韵母相同（都是huo sheng），但“火”为第三声，“获”为第四声，声调差异可能被忽略导致混淆。"
    }
  ],
  "primary_collocate": "者",
  "collocation_distractors": [
    {
      "word": "胜利",
      "explanation": "“胜利”是名词，与“获胜”搭配不成立，正确用法是“获得胜利”或“取得胜利”。"
    },
    {
      "word": "赢",
      "explanation": "“赢”是动词，可以说“赢比赛”，但不说“获胜赢”，两者不能直接组合。"
    },
    {
      "word": "冠军",
      "explanation": "“冠军”是名词，正确搭配是“赢得冠军”，而不是“获胜冠军”。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "成功",
    "explanation": "“获胜成功”看似合理，但实际不搭配，正确应为“取得成功”或“获胜”。"
  },
  "cloze_distractors": [
    {
      "word": "失败",
      "reason": "“失败”是“获胜”的反义词，填入句子意思相反，属于错误语义。"
    },
    {
      "word": "放弃",
      "reason": "“放弃”表示不再努力，与句子中坚持并最终获胜的语境矛盾，属于语义不匹配。"
    },
    {
      "word": "赶超",
      "reason": "“赶超”强调超越对手，但未明确最终结果，与“获胜”的直接结果不同，属于无关动作。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他获胜了比赛。",
      "reason": "“获胜”是不及物动词，不能直接带宾语“比赛”，应改为“他在比赛中获胜”或“他赢得了比赛”。"
    },
    {
      "sentence": "这件事获胜了。",
      "reason": "“获胜”通常用于竞争性场景（比赛、选举等），不能用于无竞争的一般事件，语义不当。"
    },
    {
      "sentence": "他获胜在比赛中。",
      "reason": "语序错误，应把地点状语“在比赛中”放在动词前，改为“他在比赛中获胜”。"
    }
  ],
  "spot_incorrect": {
    "sentence": "他努力获胜了比赛。",
    "error_description": "“获胜”是不及物动词，不能直接带宾语“比赛”，应改为“赢得了比赛”或使用正确结构。",
    "corrected": "他努力赢得了比赛。"
  },
  "word_family_forms": [
    "获胜者",
    "获胜方"
  ],
  "word_family_fake_forms": [
    "获胜性",
    "获胜化",
    "获胜度"
  ],
  "syn_ant_candidates": [
    {"word": "取胜", "relation": "synonym"},
    {"word": "胜利", "relation": "synonym"},
    {"word": "失败", "relation": "antonym"},
    {"word": "落败", "relation": "antonym"}
  ],
  "particle_candidates": null
}
